exercises.solutionCode:
using System.Text.Json;
var book = new Book("Moon Trip");
File.WriteAllText("book.json", JsonSerializer.Serialize(book));
var loaded = JsonSerializer.Deserialize<Book>(File.ReadAllText("book.json"));
Console.WriteLine(loaded?.Title);
record Book(string Title);
